            dd_peak = df['Close'].iloc[:i+1].max()
    else:
        if in_dd:
            trough = df.loc[df['Date'] >= dd_start, 'Drawdown'].min()
            trough_date = df.loc[df['Date'] >= dd_start, 'Date'].iloc[
                df.loc[df['Date'] >= dd_start, 'Drawdown'].values.argmin()
            ]
            dd_episodes.append({
                'peak_date': dd_peak,
                'trough_date': trough_date,
                'recovery_date': df['Date'].iloc[i],
                'drawdown': trough,
