with open('/app/output/final_report.html', 'w', encoding='utf-8') as f:
    f.write(html)

print("Report generated successfully at /app/output/final_report.html")
print(f"Key metrics:")
print(f"  Cumulative Return: {cumulative_return:.1f}%")
print(f"  CAGR: {cagr:.1f}%")
print(f"  Max Drawdown: {max_drawdown:.1f}%")
print(f"  Annualized Volatility: {annualized_vol:.1f}%")
print(f"  Total Dividends: ${total_dividends:.2f}")
print(f"  ATH: ${ath_price:.2f} on {ath_date}")
print(f"  ATL: ${atl_price:.2f} on {atl_date}")
print(f"  Stock Splits: {len(splits)} events")
print(f"  Dividend Events: {len(div_data)}")

import pandas as pd
import numpy as np
import json
import os

# ============================================================
# 1. LOAD DATA
# ============================================================
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'], utc=True)
df = df.sort_values('Date').reset_index(drop=True)
df['Year'] = df['Date'].dt.year
df['Decade'] = (df['Year'] // 10) * 10

first_date = df['Date'].iloc[0]
last_date = df['Date'].iloc[-1]
first_close = df['Close'].iloc[0]
last_close = df['Close'].iloc[-1]
total_years = (last_date - first_date).days / 365.25

# ============================================================
# 2. COMPUTE KPIs
# ============================================================

# Cumulative Total Return
cumulative_return = (last_close / first_close - 1) * 100

# CAGR
cagr = ((last_close / first_close) ** (1 / total_years) - 1) * 100

# Daily returns
df['Daily_Return'] = df['Close'].pct_change()
# For volatility, exclude early period with identical OHLC (zero returns)
df_vol = df[df['Volume'] > 0].copy()  # volume > 0 means reliable price data
daily_ret_vol = df_vol['Daily_Return'].dropna()
annualized_vol = daily_ret_vol.std() * np.sqrt(252) * 100

# Maximum Drawdown
df['Running_Max'] = df['Close'].cummax()
df['Drawdown'] = (df['Close'] - df['Running_Max']) / df['Running_Max'] * 100
max_drawdown = df['Drawdown'].min()
max_dd_date = df.loc[df['Drawdown'].idxmin(), 'Date']
max_dd_peak_date = df.loc[:df['Drawdown'].idxmin(), 'Close'].idxmax()
max_dd_peak_date_val = df.loc[max_dd_peak_date, 'Date']

# Total Dividends
total_dividends = df['Dividends'].sum()

# Stock Splits
splits = df[df['Stock Splits'] != 0.0][['Date', 'Stock Splits']].copy()

# ============================================================
# 3. BULL/BEAR PHASES & SUB-PERIOD CAGR
# ============================================================

# Major market events / sub-periods
sub_periods = {
    '1972–1980 (Oil Crisis Era)': ('1972-06-01', '1980-12-31'),
    '1980–1990 (Bull Market & Black Monday)': ('1980-01-01', '1989-12-31'),
    '1990–2000 (Dot-Com Era)': ('1990-01-01', '1999-12-31'),
    '2000–2010 (GFC Decade)': ('2000-01-01', '2009-12-31'),
    '2010–2020 (Post-GFC Recovery)': ('2010-01-01', '2019-12-31'),
    '2020–2026 (COVID & Recovery)': ('2020-01-01', '2026-12-31'),
}

sub_cagr = {}
for label, (start, end) in sub_periods.items():
    mask = (df['Date'] >= pd.Timestamp(start, tz='UTC')) & (df['Date'] <= pd.Timestamp(end, tz='UTC'))
    subset = df[mask]
    if len(subset) > 1:
        s = subset['Close'].iloc[0]
        e = subset['Close'].iloc[-1]
        yrs = (subset['Date'].iloc[-1] - subset['Date'].iloc[0]).days / 365.25
        if yrs > 0 and s > 0:
            sub_cagr[label] = ((e / s) ** (1 / yrs) - 1) * 100
        else:
            sub_cagr[label] = 0.0
    else:
        sub_cagr[label] = 0.0

# ============================================================
# 4. ALL-TIME HIGH / LOW
# ============================================================
ath_idx = df['Close'].idxmax()
ath_price = df['Close'].iloc[ath_idx]
ath_date = df['Date'].iloc[ath_idx]

atl_idx = df['Close'].idxmin()
atl_price = df['Close'].iloc[atl_idx]
atl_date = df['Date'].iloc[atl_idx]

# ============================================================
# 5. WORST DRAWDOWN EPISODES
# ============================================================
# Find top 5 drawdown episodes
dd_episodes = []
in_dd = False
dd_start = None
dd_peak = None
for i in range(len(df)):
    if df['Drawdown'].iloc[i] < -0.01:  # in drawdown
        if not in_dd:
            in_dd = True
            dd_start = df['Date'].iloc[i]
            # Find the peak just before this
            dd_peak = df['Close'].iloc[:i+1].max()
    else:
        if in_dd:
            trough = df.loc[df['Date'] >= dd_start, 'Drawdown'].min()
            trough_date = df.loc[df['Date'] >= dd_start, 'Date'].iloc[
                df.loc[df['Date'] >= dd_start, 'Drawdown'].values.argmin()
            ]
            dd_episodes.append({
                'peak_date': dd_peak,
                'trough_date': trough_date,
                'recovery_date': df['Date'].iloc[i],
                'drawdown': trough,
                'peak_close': dd_peak
            })
            in_dd = False

if in_dd:
    trough = df.loc[df['Date'] >= dd_start, 'Drawdown'].min()
    trough_idx_local = df.loc[df['Date'] >= dd_start, 'Drawdown'].values.argmin()
    trough_date = df.loc[df['Date'] >= dd_start, 'Date'].iloc[trough_idx_local]
    dd_episodes.append({
        'peak_date': dd_peak,
        'trough_date': trough_date,
        'recovery_date': None,
        'drawdown': trough,
        'peak_close': dd_peak
    })

# Sort by drawdown severity
dd_episodes.sort(key=lambda x: x['drawdown'])
worst_episodes = dd_episodes[:5]

# ============================================================
# 6. DECADE-BY-DECADE METRICS
# ============================================================
decades = [1970, 1980, 1990, 2000, 2010, 2020]
decade_stats = []
for d in decades:
    mask = (df['Year'] >= d) & (df['Year'] < d + 10)
    sub = df[mask]
    if len(sub) < 2:
        continue
    start_close = sub['Close'].iloc[0]
    end_close = sub['Close'].iloc[-1]
    dec_return = (end_close / start_close - 1) * 100
    dec_yrs = (sub['Date'].iloc[-1] - sub['Date'].iloc[0]).days / 365.25
    dec_cagr = ((end_close / start_close) ** (1 / dec_yrs) - 1) * 100 if dec_yrs > 0 and start_close > 0 else 0
    # Volatility (only if we have volume data)
    sub_vol_data = sub[sub['Volume'] > 0]
    if len(sub_vol_data) > 1:
        dec_vol = sub_vol_data['Daily_Return'].dropna().std() * np.sqrt(252) * 100
    else:
        dec_vol = None
    dec_max_dd = sub['Drawdown'].min()
    dec_divs = sub['Dividends'].sum()
    dec_avg_vol = sub[sub['Volume'] > 0]['Volume'].mean() if (sub['Volume'] > 0).any() else 0
    decade_stats.append({
        'decade': f'{d}s',
        'start_close': round(start_close, 2),
        'end_close': round(end_close, 2),
        'total_return': round(dec_return, 1),
        'cagr': round(dec_cagr, 1),
        'volatility': round(dec_vol, 1) if dec_vol is not None else 'N/A',
        'max_drawdown': round(dec_max_dd, 1),
        'total_dividends': round(dec_divs, 4),
        'avg_daily_volume': int(dec_avg_vol) if dec_avg_vol > 0 else 'N/A'
    })

# ============================================================
# 7. DIVIDEND ANALYSIS
# ============================================================
div_data = df[df['Dividends'] > 0].copy()
div_data['Year'] = div_data['Date'].dt.year
annual_div = div_data.groupby('Year')['Dividends'].sum().reset_index()
annual_div.columns = ['Year', 'Total_Dividends']

# Dividend yield approximation (annual dividend / avg close that year)
yearly_close = df.groupby('Year')['Close'].mean().reset_index()
yearly_close.columns = ['Year', 'Avg_Close']
div_yield_df = annual_div.merge(yearly_close, on='Year', how='left')
div_yield_df['Yield'] = (div_yield_df['Total_Dividends'] / div_yield_df['Avg_Close']) * 100

# ============================================================
# 8. VOLUME ANALYSIS
# ============================================================
df_with_vol = df[df['Volume'] > 0].copy()
vol_by_year = df_with_vol.groupby('Year')['Volume'].mean().reset_index()
vol_by_year.columns = ['Year', 'Avg_Volume']

# Top 10 highest volume days
top_vol_days = df_with_vol.nlargest(10, 'Volume')[['Date', 'Close', 'Volume']].copy()

# ============================================================
# 9. GENERATE PLOTLY CHARTS AS JSON
# ============================================================

# Helper: format date for display
def fmt_date(d):
    if hasattr(d, 'strftime'):
        return d.strftime('%Y-%m-%d')
    return str(d)

# Chart 1: Long-Term Price Trend
price_trace = {
    'x': [d.strftime('%Y-%m-%d') for d in df['Date']],
    'y': df['Close'].round(2).tolist(),
    'type': 'scatter',
