}
dy_chart = json.dumps([dy_trace], default=str)
dy_layout_json = json.dumps(dy_layout, default=str)

# Chart 7: Decade Comparison Bar Charts
dec_labels = [d['decade'] for d in decade_stats]
dec_returns = [d['total_return'] for d in decade_stats]
dec_cagrs = [d['cagr'] for d in decade_stats]

dec_ret_trace = {
    'x': dec_labels,
    'y': dec_returns,
    'type': 'bar',
